/**
 * Domain model for background terminals.
 *
 * A "terminal" is one long-running shell process started by the model. It
 * receives no stdin (launched with stdin: "ignore"), captures stdout and
 * stderr separately, and settles exactly once into a final state.
 */

export type TerminalStatus = "running" | "done" | "failed" | "killed";
// "done"   = exited with code 0
// "failed" = exited non-zero, or a spawn-level runtime error after start
// "killed" = terminated by bg_kill, the /ps UI, or session teardown

/** Read-only view over one captured output stream (stdout or stderr). */
export interface OutputView {
	/** Decoded, possibly head-trimmed text (bounded by the in-memory cap). */
	readonly text: string;
	/** True total bytes ever received on this stream. */
	readonly totalBytes: number;
	/** Bytes dropped from the head of the in-memory view (0 = complete). */
	readonly truncatedBytes: number;
	/** On-disk full capture; always the complete stream when spilling works. */
	readonly spillPath?: string;
}

export interface TerminalSnapshot {
	readonly id: string;
	/** Exactly the command line the model asked to run. */
	readonly command: string;
	/** Short model-provided name, shown in listings and the UI. */
	readonly title: string;
	/** Resolved absolute cwd the process runs in. */
	readonly cwd: string;
	/** Undefined only if spawn itself failed before a pid was assigned. */
	readonly pid?: number;
	readonly status: TerminalStatus;
	/** Date.now() at spawn. */
	readonly createdAt: number;
	/** Date.now() at settle (exit/kill). */
	readonly settledAt?: number;
	/** Set when the process exited via exit code (exactly one of exitCode/signal). */
	readonly exitCode?: number;
	/** Set when the process was terminated by a signal, e.g. "SIGTERM". */
	readonly signal?: string;
	/** Spawn error / kill-escalation notes, bounded. */
	readonly errorText?: string;
	readonly stdout: OutputView;
	readonly stderr: OutputView;
}

export function formatElapsed(snap: TerminalSnapshot) {
	const end = snap.settledAt ?? Date.now();
	const totalSeconds = Math.max(0, Math.round((end - snap.createdAt) / 1000));
	const minutes = Math.floor(totalSeconds / 60);
	const seconds = totalSeconds % 60;
	return minutes > 0
		? `${minutes}m${seconds.toString().padStart(2, "0")}s`
		: `${seconds}s`;
}

/** "exit 0", "exit 137", "SIGTERM", or "running". */
export function formatExit(snap: TerminalSnapshot) {
	if (snap.status === "running") return "running";
	if (snap.signal) return snap.signal;
	if (snap.exitCode !== undefined) return `exit ${snap.exitCode}`;
	return snap.status;
}

// --- Errors -------------------------------------------------------------------

export class SpawnError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "SpawnError";
	}
}

export class ConcurrencyLimitError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "ConcurrencyLimitError";
	}
}

export class UnknownTerminalError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "UnknownTerminalError";
	}
}

/**
 * TerminalManager — owns the registry of running/settled background
 * terminals.
 *
 * Each terminal is a raw `node:child_process` spawn (own process group on
 * POSIX, stdin ignored) whose stdout/stderr 'data' callbacks fold into two
 * bounded OutputBuffers. Closing a terminal's scope kills the whole process
 * tree (SIGTERM → SIGKILL escalation).
 *
 * The manager also exposes a synchronous `TerminalReadModel` so the
 * imperative TUI components (which render synchronously) can read snapshots
 * and issue fire-and-forget kills without touching async coordination.
 *
 * Plain TypeScript port of the original Effect-based implementation. The
 * async core is small: Deferred is replaced with Promise + resolve, FiberSet
 * with a self-removing cleanup-task set, and Effect.addFinalizer with the
 * explicit `disposed` flag checked in `start()` and torn down by
 * `disposeAll()`.
 */

import { spawn, type ChildProcess } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import {
	ConcurrencyLimitError,
	formatExit,
	SpawnError,
	UnknownTerminalError,
	type TerminalSnapshot,
	type TerminalStatus,
} from "./domain.ts";
import { OutputBuffer } from "./output.ts";

export const MAX_RUNNING = 8;
export const MAX_TRACKED = 32;
const MAX_SETTLED_HISTORY = MAX_TRACKED * 4;
/** In-memory retained cap per stream. */
export const RETAINED_PER_STREAM = 2 * 1024 * 1024;
/** Private full-log spills are bounded so a firehose cannot fill the temp disk. */
export const MAX_SPILL_BYTES_PER_STREAM = 256 * 1024 * 1024;
const STOP_TIMEOUT_MS = 5_000;
/** SIGTERM is normally enough; the second deadline covers a wedged process. */
const FORCE_KILL_AFTER_MS = 2_000;
/** After termination, how long to wait for the natural close→flush→settle
 * path before force-settling (a grandchild can hold the stdio pipes open). */
const SETTLE_GRACE_MS = 1_000;
/** Bound on waiting for spill WriteStreams to flush before settling; a hung
 * filesystem must not leave an exited entry "running" (and kill() waiting).
 * Terminate (≤2.5s) + settle grace (1s) + flush (1.5s) stays inside the 5s
 * scope-close bound, so teardown remains bounded end to end. */
const SPILL_FLUSH_TIMEOUT_MS = 1_500;
const ERROR_TEXT_MAX_LENGTH = 4_096;

function bounded(text: string) {
	return text.slice(0, ERROR_TEXT_MAX_LENGTH);
}

function boundedError(error: unknown) {
	return bounded(error instanceof Error ? error.message : String(error));
}

// --- Internal state -----------------------------------------------------------

/** Mutable snapshot; exposed to readers via the readonly TerminalSnapshot type.
 * stdout/stderr are getters over the live OutputBuffers. */
interface MutableSnapshot extends TerminalSnapshot {
	status: TerminalStatus;
	pid?: number;
	settledAt?: number;
	exitCode?: number;
	signal?: string;
	errorText?: string;
}

interface Entry {
	snapshot: MutableSnapshot;
	child: ChildProcess;
	stdoutBuf: OutputBuffer;
	stderrBuf: OutputBuffer;
	spillStreams: fs.WriteStream[];
	/** Set in the same synchronous block that sends SIGTERM so a natural exit
	 * before signaling keeps its truthful status. */
	killSignaled: boolean;
	/** The child emitted 'error' (spawn failure etc.); settles as "failed".
	 * Kept separate from errorText, which also carries non-fatal notes
	 * (spill failures) that must not flip a clean exit to "failed". */
	processErrored: boolean;
	/** 'exit' event observed (code/signal recorded). */
	exited: boolean;
	/** 'close' event observed (stdio flushed; the settle trigger). */
	stdioClosed: boolean;
	/** A settle-after-spill-flush is in flight; don't start a second one. */
	settling: boolean;
	/** The shell exited without stdio closing; a bounded scope close is queued
	 * to reap descendants that still hold the inherited pipes open. */
	exitCleanupStarted: boolean;
	/** Completed exactly once when the entry settles. Kill callers and the
	 * teardown path can all await the same result without missing a
	 * notification. Replaces Effect Deferred. */
	settledPromise: Promise<void>;
	settledResolve: () => void;
	/** Idempotent close-in-progress flag + promise for closeEntryScope. */
	closing: boolean;
	closingPromise?: Promise<void>;
}

export interface StartOptions {
	readonly command: string;
	readonly title: string;
	readonly cwd: string;
}

export interface KillResult {
	readonly id: string;
	readonly title: string;
	readonly status: TerminalStatus;
	/** True when the entry was still running when this kill began. */
	readonly wasRunning: boolean;
	/** True when this call initiated the termination AND the entry settled as
	 * killed (a natural exit that won the race reports killed: false). */
	readonly killed: boolean;
	/** Final exit rendering ("exit 0", "SIGTERM", ...) captured at settle time,
	 * so reports stay accurate even if the entry is pruned afterwards. */
	readonly exit: string;
}

// --- Read model ----------------------------------------------------------------

/** Synchronous bridge for the TUI. Snapshots are live objects; do not mutate. */
export interface TerminalReadModel {
	list(): ReadonlyArray<TerminalSnapshot>;
	get(id: string): TerminalSnapshot | undefined;
	size(): number;
	/** Any-change notification (widget, /ps list). */
	subscribe(listener: () => void): () => void;
	/** Per-terminal notification (/ps detail view). */
	subscribeTo(id: string, listener: () => void): () => void;
	/** Fire-and-forget kill (dashboard/detail `x`). Not marked consumed: the
	 * settle still flows back to the model as a follow-up message. */
	requestKill(id: string): void;
	/**
	 * Register the settle hook. `consumed` is true when an active bg_kill is
	 * collecting the result (so it must not also be delivered as a follow-up).
	 */
	setOnSettled(
		hook: ((snap: TerminalSnapshot, consumed: boolean) => void) | undefined,
	): void;
}

// --- Process helpers ------------------------------------------------------------

function shellInvocation(command: string) {
	if (process.platform === "win32") {
		const shell = process.env.ComSpec ?? "cmd.exe";
		return { shell, args: ["/d", "/s", "/c", command] };
	}
	return { shell: "/bin/sh", args: ["-c", command] };
}

/** Signal the whole process group on POSIX so descendants (servers a shell
 * command spawned) die with it; a wedged child must not orphan its tree. */
function killTree(child: ChildProcess, signal: NodeJS.Signals) {
	if (process.platform === "win32" && child.pid) {
		try {
			const killer = spawn(
				"taskkill",
				[
					"/pid",
					String(child.pid),
					"/T",
					...(signal === "SIGKILL" ? ["/F"] : []),
				],
				{ stdio: "ignore", windowsHide: true },
			);
			killer.once("error", () => {
				try {
					child.kill(signal);
				} catch {
					// Process may already be gone.
				}
			});
			killer.once("exit", (code) => {
				if (code === 0) return;
				try {
					child.kill(signal);
				} catch {
					// Process may already be gone.
				}
			});
			killer.unref();
			return;
		} catch {
			// Fall through to the direct signal when taskkill cannot be launched.
		}
	}
	if (process.platform !== "win32" && child.pid) {
		try {
			process.kill(-child.pid, signal);
			return;
		} catch {
			// Group may already be gone; fall through to the direct signal.
		}
	}
	try {
		child.kill(signal);
	} catch {
		// Process may already be gone.
	}
}

/** Resolve once the child emits 'close', or after `timeoutMs` regardless.
 * Replaces Effect's callback + timeout race. */
function waitForClose(child: ChildProcess, closed: () => boolean, timeoutMs: number): Promise<void> {
	if (closed()) return Promise.resolve();
	return new Promise<void>((resolve) => {
		let done = false;
		const finish = () => {
			if (done) return;
			done = true;
			child.off("close", finish);
			clearTimeout(timer);
			resolve();
		};
		child.once("close", finish);
		const timer = setTimeout(finish, timeoutMs);
		// Clear the timer on the happy path so the deadline doesn't fire as a
		// no-op after 'close' already resolved.
		// NOTE: do NOT unref — this timer is the bound guarantee that the
		// promise resolves; unref'ing it lets the event loop empty first.
	});
}

/** SIGTERM → deadline → SIGKILL; waits for stdio closure rather than only the
 * shell's exit because descendants can keep the inherited pipes and process
 * group alive after the shell itself is gone. */
async function terminateChild(
	child: ChildProcess,
	closed: () => boolean,
	onSignal: () => void,
) {
	if (closed()) return;
	onSignal();
	killTree(child, "SIGTERM");
	await waitForClose(child, closed, FORCE_KILL_AFTER_MS);
	if (closed()) return;
	killTree(child, "SIGKILL");
	await waitForClose(child, closed, 500);
}

/** Race a promise against a timeout; resolves void either way. The timer is
 * cleared on the happy path so a no-op deadline cannot keep the event loop
 * (and pi's shutdown) alive past teardown. NOT unref'd — the timer is the
 * bound guarantee the promise resolves when `p` hangs (e.g. a wedged
 * disposeAll); unref'ing it would let the loop empty first and stall teardown. */
function withTimeoutVoid(p: Promise<unknown>, timeoutMs: number): Promise<void> {
	return new Promise<void>((resolve) => {
		const timer = setTimeout(() => resolve(), timeoutMs);
		p.then(
			() => {
				clearTimeout(timer);
				resolve();
			},
			() => {
				clearTimeout(timer);
				resolve();
			},
		);
	});
}

function sleep(ms: number): Promise<void> {
	return new Promise((resolve) => {
		const timer = setTimeout(resolve, ms);
		// scheduleExitCleanup uses this as a 1s grace before a no-op check; once
		// the entry settles the check is harmless. Unref so the timer doesn't
		// pin the event loop through shutdown — the runCleanup task completes
		// whenever it fires, and a withTimeoutVoid bounds disposeAll anyway.
		timer.unref?.();
	});
}

// --- Implementation --------------------------------------------------------------

export class TerminalManager {
	private readonly entries = new Map<string, Entry>();
	/** Small immutable tombstones preserve truthful kill reports if pruning
	 * races the tool boundary after an id was validated. */
	private readonly settledHistory = new Map<
		string,
		Pick<KillResult, "title" | "status" | "exit">
	>();
	/** ids with an in-flight kill() collecting the result (settle → consumed). */
	private readonly killInterest = new Map<string, number>();
	private readonly listeners = new Set<() => void>();
	private readonly idListeners = new Map<string, Set<() => void>>();
	/** Fire-and-forget cleanup tasks; self-removing on completion. Replaces
	 * Effect's FiberSet. */
	private readonly cleanupTasks = new Set<Promise<void>>();
	private counter = 0;
	private reserved = 0;
	private disposed = false;
	private spillDir: string | undefined | null;
	private onSettled:
		| ((snap: TerminalSnapshot, consumed: boolean) => void)
		| undefined;

	readonly view: TerminalReadModel;

	constructor() {
		const self = this;
		this.view = {
			list: () => [...self.entries.values()].map((entry) => entry.snapshot),
			get: (id) => self.entries.get(id)?.snapshot,
			size: () => self.entries.size,
			subscribe: (listener) => {
				self.listeners.add(listener);
				return () => self.listeners.delete(listener);
			},
			subscribeTo: (id, listener) => {
				let set = self.idListeners.get(id);
				if (!set) {
					set = new Set();
					self.idListeners.set(id, set);
				}
				set.add(listener);
				return () => {
					set!.delete(listener);
					if (set!.size === 0) self.idListeners.delete(id);
				};
			},
			requestKill: (id) => {
				const entry = self.entries.get(id);
				if (!entry) return;
				// UI-initiated kills are not "consumed": the killed result still
				// flows back to the model as a follow-up message (subagents
				// precedent).
				if (entry.snapshot.status !== "running") return;
				self.runCleanup(withTimeoutVoid(self.closeEntryScope(entry), STOP_TIMEOUT_MS));
			},
			setOnSettled: (hook) => {
				self.onSettled = hook;
			},
		};
	}

	// --- Notification + cleanup plumbing ----------------------------------

	private notify(id?: string) {
		for (const listener of [...this.listeners]) {
			try {
				listener();
			} catch {
				// A failed widget/render listener must not corrupt lifecycle state.
			}
		}
		if (id) {
			for (const listener of this.idListeners.get(id) ?? []) {
				try {
					listener();
				} catch {
					// Same.
				}
			}
		}
	}

	/** Fire-and-forget a promise; self-removes from cleanupTasks on completion.
	 * Replaces Effect's FiberSet.runtime(). */
	private runCleanup(p: Promise<unknown>): void {
		const tracked = p.then(() => {}, () => {}) as Promise<void>;
		this.cleanupTasks.add(tracked);
		tracked.finally(() => this.cleanupTasks.delete(tracked));
	}

	/** Wait for all in-flight fire-and-forget cleanup to finish. */
	private awaitCleanup(): Promise<void> {
		return Promise.all([...this.cleanupTasks]).then(() => {});
	}

	// --- Concurrency + kill interest --------------------------------------

	private runningCount(): number {
		return [...this.entries.values()].filter(
			(e) => e.snapshot.status === "running",
		).length;
	}

	private addKillInterest(ids: ReadonlyArray<string>) {
		for (const id of ids)
			this.killInterest.set(id, (this.killInterest.get(id) ?? 0) + 1);
	}

	private releaseKillInterest(ids: ReadonlyArray<string>) {
		for (const id of ids) {
			const count = (this.killInterest.get(id) ?? 1) - 1;
			if (count <= 0) this.killInterest.delete(id);
			else this.killInterest.set(id, count);
		}
	}

	private pruneSettled() {
		if (this.entries.size <= MAX_TRACKED) return;
		const candidates = [...this.entries.values()]
			.filter(
				(e) =>
					e.snapshot.status !== "running" &&
					!this.killInterest.has(e.snapshot.id),
			)
			.sort(
				(a, b) =>
					(a.snapshot.settledAt ?? a.snapshot.createdAt) -
					(b.snapshot.settledAt ?? b.snapshot.createdAt),
			);
		for (const entry of candidates) {
			if (this.entries.size <= MAX_TRACKED) break;
			this.entries.delete(entry.snapshot.id);
			this.runCleanup(this.closeEntryScope(entry));
		}
	}

	// --- Spill plumbing ---------------------------------------------------

	private resolveSpillDir(): string | undefined {
		if (this.spillDir !== undefined) return this.spillDir ?? undefined;
		try {
			const base = path.join(os.tmpdir(), "pi-background-terminals");
			fs.mkdirSync(base, { recursive: true, mode: 0o700 });
			fs.chmodSync(base, 0o700);
			// Reap stale session dirs from prior sessions that crashed (SIGKILL,
			// power loss) before session_shutdown → disposeAll could clean up.
			// Their spill files contain process output (build logs, env dumps,
			// tokens) and must not persist indefinitely. Dirs are named
			// `session-<pid>-<suffix>`; reaping skips dirs whose PID is still alive
			// (probed via process.kill(pid, 0)), only dead-PID (or unparseable/
			// old-format) dirs are reaped. This prevents deleting a live
			// concurrent session's spill dir.
			try {
				for (const name of fs.readdirSync(base)) {
					if (!name.startsWith("session-")) continue;
					// session-<pid>-<suffix>: parse the pid between the first and second
					// `-` after `session-`. Missing third segment or NaN → stale.
					const rest = name.slice("session-".length);
					const firstDash = rest.indexOf("-");
					const pidStr = firstDash === -1 ? "" : rest.slice(0, firstDash);
					const pid = Number(pidStr);
					if (!Number.isInteger(pid) || pid <= 0) {
						const stale = path.join(base, name);
						try {
							fs.rmSync(stale, { recursive: true, force: true });
						} catch {
							// One stale dir we can't remove must not block the new session.
						}
						continue;
					}
					try {
						process.kill(pid, 0);
						// Alive → live concurrent session (or this very process); SKIP.
						continue;
					} catch (e) {
						const code = (e as NodeJS.ErrnoException).code;
						if (code === "ESRCH") {
							const stale = path.join(base, name);
							try {
								fs.rmSync(stale, { recursive: true, force: true });
							} catch {
								// One stale dir we can't remove must not block the new session.
							}
						} else if (code === "EPERM") {
							// Not ours but alive → SKIP to be safe.
							continue;
						} else {
							const stale = path.join(base, name);
							try {
								fs.rmSync(stale, { recursive: true, force: true });
							} catch {
								// One stale dir we can't remove must not block the new session.
							}
						}
					}
				}
			} catch {
				// readdir failure (base not readable) is non-fatal.
			}
			this.spillDir = fs.mkdtempSync(path.join(base, `session-${process.pid}-`));
			fs.chmodSync(this.spillDir, 0o700);
		} catch {
			this.spillDir = null;
		}
		return this.spillDir ?? undefined;
	}

	private makeSpill(
		entryRef: () => Entry | undefined,
		id: string,
		stream: "stdout" | "stderr",
		resumeSource: () => void,
	): { spillPath: string; file: fs.WriteStream; write: (chunk: string) => boolean } | undefined {
		const dir = this.resolveSpillDir();
		if (!dir) return undefined;
		const spillPath = path.join(dir, `${id}.${stream}.log`);
		try {
			const file = fs.createWriteStream(spillPath, {
				flags: "a",
				mode: 0o600,
			});
			let broken = false;
			let capped = false;
			let writtenBytes = 0;
			file.on("error", (error) => {
				broken = true;
				resumeSource();
				const current = entryRef();
				if (current) {
					const buf =
						stream === "stdout" ? current.stdoutBuf : current.stderrBuf;
					buf.spillPath = undefined;
					current.snapshot.errorText ??= bounded(
						`Full-log spill to ${spillPath} failed: ${boundedError(error)}`,
					);
				}
			});
			return {
				spillPath,
				file,
				write: (chunk: string) => {
					// writableEnded guard: late 'data' after the settle flush must not
					// error the ended stream (and falsely report the spill as broken).
					if (broken || capped || file.writableEnded) return true;
					const chunkBytes = Buffer.byteLength(chunk, "utf8");
					if (writtenBytes + chunkBytes > MAX_SPILL_BYTES_PER_STREAM) {
						capped = true;
						const current = entryRef();
						if (current) {
							const buf =
								stream === "stdout" ? current.stdoutBuf : current.stderrBuf;
							buf.spillPath = undefined;
							current.snapshot.errorText ??= bounded(
								`${stream} full-log spill reached the ${MAX_SPILL_BYTES_PER_STREAM}-byte safety limit`,
							);
						}
						return true;
					}
					writtenBytes += chunkBytes;
					let accepted = true;
					try {
						accepted = file.write(chunk);
					} catch {
						// A WriteStream that hit a write error (disk-full EIO/ENOSPC,
						// EPIPE) transitions to destroyed and throws on the next
						// write — before our 'error' listener sets `broken`. This runs
						// inside the child's stdout/stderr 'data' handler, so an
						// uncaught throw would crash pi. Treat a throw as broken.
						broken = true;
						resumeSource();
						return true;
					}
					if (!accepted) file.once("drain", resumeSource);
					return accepted;
				},
			};
		} catch {
			return undefined;
		}
	}

	// --- Settle / flush / teardown ---------------------------------------

	/** End all spill streams; resolves when their buffers are flushed to disk
	 * (bounded), so a settle notification never points at a partial file. */
	private async flushSpillStreams(entry: Entry): Promise<void> {
		const streams = entry.spillStreams;
		entry.spillStreams = [];
		const flushes = streams.map(
			(stream) =>
				new Promise<void>((resolve) => {
					const done = () => resolve();
					try {
						stream.end(done);
					} catch {
						// Best effort; tmpdir contents are disposable.
						done();
					}
				}),
		);
		let timer: ReturnType<typeof setTimeout> | undefined;
		try {
			const timedOut = await Promise.race([
				Promise.all(flushes).then(() => false),
				new Promise<boolean>((resolve) => { timer = setTimeout(() => resolve(true), SPILL_FLUSH_TIMEOUT_MS); }),
			]);
			if (timedOut) {
				entry.stdoutBuf.spillPath = undefined;
				entry.stderrBuf.spillPath = undefined;
				entry.snapshot.errorText ??=
					"Full-log spill flush timed out; full output may be incomplete";
				// Force-close the FDs so a hung filesystem cannot leak descriptors
				// (or block process exit) past teardown. flushSpillStreams already
				// reassigned entry.spillStreams to [] earlier, so nothing else closes them.
				for (const stream of streams) {
					try {
						stream.destroy();
					} catch {
						// Best effort; tmpdir contents are disposable.
					}
				}
			}
		} finally {
			if (timer) clearTimeout(timer);
		}
	}

	/** Single settle path — idempotent; kill vs natural exit vs error races are
	 * resolved by whichever lands first (the second call is a no-op). */
	private settle(entry: Entry) {
		const s = entry.snapshot;
		if (s.status !== "running") return;
		s.settledAt = Date.now();
		s.status = entry.killSignaled
			? "killed"
			: entry.processErrored
				? "failed"
				: s.exitCode === 0
					? "done"
					: "failed";
		this.settledHistory.set(s.id, {
			title: s.title,
			status: s.status,
			exit: formatExit(s),
		});
		while (this.settledHistory.size > MAX_SETTLED_HISTORY) {
			const oldest = this.settledHistory.keys().next().value;
			if (oldest === undefined) break;
			this.settledHistory.delete(oldest);
		}
		// Resolving the settle promise can immediately resume kill waiters,
		// whose ensuring blocks release interest. Snapshot consumption first so
		// the settle hook observes the interest that existed when settlement
		// won.
		const consumed = (this.killInterest.get(s.id) ?? 0) > 0;
		entry.settledResolve();
		this.notify(s.id);
		try {
			// During teardown, don't queue results into a shutting-down session.
			if (!this.disposed) this.onSettled?.(s, consumed);
		} catch {
			// The parent session may be unavailable; settlement stays final.
		}
		this.pruneSettled();
	}

	/** Flush the spill files, then settle: the completion follow-up (and the
	 * kill() resolution) reference the spill path, so the full capture must be
	 * on disk before anyone is told about it. Idempotent via `settling`. */
	private settleAfterFlush(entry: Entry) {
		if (entry.settling || entry.snapshot.status !== "running") return;
		entry.settling = true;
		this.runCleanup(
			(async () => {
				await this.flushSpillStreams(entry);
				this.settle(entry);
			})(),
		);
	}

	private scheduleExitCleanup(entry: Entry) {
		if (entry.exitCleanupStarted) return;
		entry.exitCleanupStarted = true;
		this.runCleanup(
			(async () => {
				await sleep(SETTLE_GRACE_MS);
				if (entry.snapshot.status === "running" && !entry.stdioClosed) {
					await withTimeoutVoid(this.closeEntryScope(entry), STOP_TIMEOUT_MS);
				}
			})(),
		);
	}

	/** The ONE teardown path (idempotent via `closing` flag). Kill, requestKill,
	 * pruning, disposeAll, and scheduleExitCleanup all converge here. */
	private closeEntryScope(entry: Entry): Promise<void> {
		if (entry.closing) return entry.closingPromise ?? Promise.resolve();
		entry.closing = true;
		entry.closingPromise = (async () => {
			// Only claim "killed" when we are actually about to signal a
			// live process; a natural exit that already happened (still
			// waiting on 'close') keeps its truthful done/failed status.
			await terminateChild(entry.child, () => entry.stdioClosed, () => {
				entry.killSignaled ||=
					!entry.exited && entry.snapshot.status === "running";
			});
			// Give the natural close→flush→settle path a bounded grace,
			// then force the settle: a grandchild holding the pipe open
			// (detached into a new group) must not leave the entry
			// "running" forever.
			if (entry.snapshot.status === "running") {
				await withTimeoutVoid(entry.settledPromise, SETTLE_GRACE_MS);
			}
			if (entry.snapshot.status === "running" && !entry.settling) {
				// Force the settle ourselves. When `settling` is set, the
				// close path's flush→settle is already in flight (bounded by
				// SPILL_FLUSH_TIMEOUT_MS) — settling here first would cite a
				// spill file that is still being flushed.
				if (!entry.stdioClosed) {
					entry.snapshot.errorText ??=
						"stdio did not close after termination; output may be incomplete";
				}
				entry.settling = true;
				await this.flushSpillStreams(entry);
				this.settle(entry);
			}
		})();
		return entry.closingPromise;
	}

	// --- Public API -------------------------------------------------------

	async start(options: StartOptions): Promise<TerminalSnapshot> {
		// Reserve synchronously (before any await) so parallel tool calls
		// cannot race past the cap.
		if (this.disposed) {
			throw new SpawnError(
				"Background terminal manager is shutting down.",
			);
		}
		if (this.runningCount() + this.reserved >= MAX_RUNNING) {
			throw new ConcurrencyLimitError(
				`Max ${MAX_RUNNING} background terminals can run concurrently. Stop one with bg_kill before starting another.`,
			);
		}
		this.reserved++;

		try {
			// The entire spawn → setEncoding → on('data'/'error'/'exit'/'close')
			// → entries.set sequence must be SYNCHRONOUS (no await between the
			// reservation check and entries.set) so an abort/teardown can't
			// leave a live child no entry knows about.
			const { shell, args } = shellInvocation(options.command);
			let child: ChildProcess;
			try {
				child = spawn(shell, args, {
					cwd: options.cwd,
					env: process.env,
					// stdin IGNORED: there is no input surface, ever. A process
					// that reads stdin sees EOF immediately.
					stdio: ["ignore", "pipe", "pipe"],
					// Own process group on POSIX → group kill takes the whole tree.
					detached: process.platform !== "win32",
				});
			} catch (error) {
				throw new SpawnError(boundedError(error));
			}

			const id = `bt-${++this.counter}`;
			const entryRef = () => this.entries.get(id);
			const stdoutSpill = this.makeSpill(entryRef, id, "stdout", () =>
				child.stdout?.resume(),
			);
			const stderrSpill = this.makeSpill(entryRef, id, "stderr", () =>
				child.stderr?.resume(),
			);
			const stdoutBuf = new OutputBuffer(
				RETAINED_PER_STREAM,
				stdoutSpill?.write,
			);
			const stderrBuf = new OutputBuffer(
				RETAINED_PER_STREAM,
				stderrSpill?.write,
			);
			stdoutBuf.spillPath = stdoutSpill?.spillPath;
			stderrBuf.spillPath = stderrSpill?.spillPath;

			const snapshot: MutableSnapshot = {
				id,
				command: options.command,
				title: options.title,
				cwd: options.cwd,
				pid: child.pid,
				status: "running",
				createdAt: Date.now(),
				get stdout() {
					return stdoutBuf.view();
				},
				get stderr() {
					return stderrBuf.view();
				},
			};

			// Create settled promise (replaces Effect Deferred).
			let settledResolve!: () => void;
			const settledPromise = new Promise<void>((res) => {
				settledResolve = res;
			});

			const entry: Entry = {
				snapshot,
				child,
				stdoutBuf,
				stderrBuf,
				spillStreams: [stdoutSpill?.file, stderrSpill?.file].filter(
					(file): file is fs.WriteStream => file !== undefined,
				),
				killSignaled: false,
				processErrored: false,
				exited: false,
				stdioClosed: false,
				settling: false,
				exitCleanupStarted: false,
				settledPromise,
				settledResolve,
				closing: false,
			};

			// Plain-callback stream plumbing (the codex-backend precedent):
			// setEncoding's internal StringDecoder is multibyte-safe across
			// chunk boundaries.
			child.stdout?.setEncoding("utf8");
			child.stdout?.on("data", (chunk: string) => {
				if (!stdoutBuf.push(chunk)) child.stdout?.pause();
				this.notify(id);
			});
			child.stderr?.setEncoding("utf8");
			child.stderr?.on("data", (chunk: string) => {
				if (!stderrBuf.push(chunk)) child.stderr?.pause();
				this.notify(id);
			});
			// Spawn failures (ENOENT etc.) arrive via 'error', not a throw. Node
			// still emits 'close' afterwards (with a bogus errno as code), so
			// record the failure here and let the close path do the one settle.
			child.once("error", (error) => {
				entry.processErrored = true;
				snapshot.errorText ??= boundedError(error);
				entry.exited = true;
				this.settleAfterFlush(entry);
			});
			// Record code/signal on 'exit'; settle on 'close' so the completion
			// notification always carries the final flushed output.
			child.once("exit", (code, signal) => {
				entry.exited = true;
				snapshot.exitCode = code ?? undefined;
				snapshot.signal = signal ?? undefined;
				// A descendant can keep the pipes open after the shell exits. Give
				// close a short natural grace, then close the scope to terminate
				// the surviving process group and force a bounded settlement.
				this.scheduleExitCleanup(entry);
			});
			child.once("close", (code, signal) => {
				entry.exited = true;
				entry.stdioClosed = true;
				// Only trust close's code/signal when 'exit' never fired (a spawn
				// 'error' close reports the errno, e.g. -2, as its code).
				if (!entry.processErrored) {
					snapshot.exitCode ??= code ?? undefined;
					snapshot.signal ??= signal ?? undefined;
				}
				this.settleAfterFlush(entry);
			});

			// disposeAll may have swept the entries map while we were setting up;
			// an entry added after the sweep would never be torn down. Close our
			// own scope (kills the child) and fail instead (subagents precedent).
			if (this.disposed) {
				// Don't await — just fire and forget the close, then throw.
				this.runCleanup(this.closeEntryScope(entry));
				throw new SpawnError(
					"Background terminal manager shut down while starting.",
				);
			}
			this.entries.set(id, entry);
			this.notify(id);
			return snapshot as TerminalSnapshot;
		} finally {
			this.reserved--;
			this.notify();
		}
	}

	async status(id: string): Promise<TerminalSnapshot> {
		const entry = this.entries.get(id);
		if (!entry) {
			const known = [...this.entries.keys()];
			throw new UnknownTerminalError(
				`Unknown terminal id "${id}". Known: ${known.join(", ") || "none"}.`,
			);
		}
		return entry.snapshot as TerminalSnapshot;
	}

	/** Kill running terminals; resolves only after they have settled. */
	async kill(ids: ReadonlyArray<string>): Promise<ReadonlyArray<KillResult>> {
		const unique = [...new Set(ids)];
		const byId = new Map(
			unique
				.map((id) => this.entries.get(id))
				.filter((entry): entry is Entry => entry !== undefined)
				.map((entry) => [entry.snapshot.id, entry]),
		);
		// Validate all known first (UnknownTerminalError listing known ids).
		const unknown = unique.filter((id) => !byId.has(id));
		if (unknown.length > 0) {
			const known = [...this.entries.keys()];
			throw new UnknownTerminalError(
				`Unknown terminal id(s): ${unknown.join(", ")}. Known: ${known.join(", ") || "none"}.`,
			);
		}
		const running = [...byId.values()].filter(
			(entry) => entry.snapshot.status === "running",
		);
		const runningIds = running.map((entry) => entry.snapshot.id);
		// Mark consumed before signaling so this kill's settlements are not
		// ALSO queued as automatic follow-up messages to the model.
		this.addKillInterest(runningIds);
		try {
			// For each running entry, fire-and-forget the close (killEntry).
			for (const entry of running) {
				if (entry.snapshot.status !== "running") continue;
				this.runCleanup(
					withTimeoutVoid(this.closeEntryScope(entry), STOP_TIMEOUT_MS),
				);
			}
			// Every caller waits on the entries that were running when its kill
			// began. Settled promise completion cannot be missed and supports
			// concurrent overlapping/multi-id kill calls.
			await Promise.all(running.map((entry) => entry.settledPromise));
			// Capture the report BEFORE the ensuring below releases interest and
			// prunes — a just-settled entry must not vanish out from under it.
			return unique.map((id): KillResult => {
				const snapshot = byId.get(id)?.snapshot;
				const history = this.settledHistory.get(id);
				const status = snapshot?.status ?? history?.status ?? "killed";
				const wasRunning = runningIds.includes(id);
				return {
					id,
					title: snapshot?.title ?? history?.title ?? "?",
					status,
					wasRunning,
					// A natural exit can win the race with our SIGTERM; report what
					// actually happened rather than claiming the kill did it.
					killed: wasRunning && status === "killed",
					exit: snapshot
						? formatExit(snapshot)
						: (history?.exit ?? "unknown"),
				};
			});
		} finally {
			this.releaseKillInterest(runningIds);
			this.pruneSettled();
		}
	}

	list(): TerminalSnapshot[] {
		return [...this.entries.values()].map((e) => e.snapshot);
	}

	async disposeAll(): Promise<void> {
		this.disposed = true;
		const all = [...this.entries.values()];
		this.entries.clear();
		await Promise.all(
			all.map((entry) =>
				withTimeoutVoid(this.closeEntryScope(entry), STOP_TIMEOUT_MS),
			),
		);
		// Detached kill/prune/flush work is tracked in cleanupTasks. Wait for
		// it within the shutdown bound; remaining tasks self-remove.
		await withTimeoutVoid(this.awaitCleanup(), STOP_TIMEOUT_MS);
		const dir = this.spillDir;
		this.spillDir = null;
		if (dir) {
			try {
				fs.rmSync(dir, { recursive: true, force: true });
			} catch {
				// Best effort; tmpdir contents are disposable.
			}
		}
		this.notify();
	}
}

/** All model-facing strings for the background-terminals tools. */

import {
	DEFAULT_MAX_BYTES,
	DEFAULT_MAX_LINES,
	formatSize,
	truncateTail,
} from "@earendil-works/pi-coding-agent";
import { formatElapsed, formatExit, type TerminalSnapshot } from "./domain.ts";
import { MAX_RUNNING, type KillResult } from "./manager.ts";

/** bg_status stdout tail. */
export const STATUS_STDOUT_MAX = 16 * 1024;
/** bg_status stderr tail. */
export const STATUS_STDERR_MAX = 8 * 1024;
/** Completion follow-up stdout tail. Keep this concise; /ps has the detailed view. */
export const RESULT_STDOUT_MAX = 8 * 1024;
/** Completion follow-up stderr tail. Keep this concise; /ps has the detailed view. */
export const RESULT_STDERR_MAX = 4 * 1024;
const STATUS_STDOUT_MAX_LINES = 400;
const STATUS_STDERR_MAX_LINES = 200;
const RESULT_STDOUT_MAX_LINES = 40;
const RESULT_STDERR_MAX_LINES = 20;

export const BG_START_TOOL_DESCRIPTION =
	"Start a long-running shell command as a background terminal (executed via the platform shell — sh -c on POSIX, cmd.exe /d /s /c on Windows). " +
	"Fire-and-forget: this returns immediately with an id, and you get a message with the final output when the process exits. " +
	"The process receives NO stdin (immediate EOF) and there is no way to send input later — interactive commands will not work; use bg_kill to stop a stuck one. " +
	`Terminals are session-scoped: they are killed when the session ends or reloads. Output shown to you is tail-truncated (stdout ${formatSize(STATUS_STDOUT_MAX)}, stderr ${formatSize(STATUS_STDERR_MAX)}); the full logs are captured to files and in the /ps viewer. ` +
	`Max ${MAX_RUNNING} background terminals can run at once.`;

export const BG_START_PROMPT_SNIPPET =
	"Run a long-lived shell command in the background (dev servers, builds, watchers); output is captured and you're notified on exit";

export const BG_START_PROMPT_GUIDELINES = [
	"Use bg_start for commands expected to run long or indefinitely (servers, watch modes, long builds); use the regular bash tool for quick commands.",
	"bg_start processes receive no stdin — never start a command that requires interactive input.",
	"After bg_start, keep working; the exit result arrives automatically. Use bg_status only when you need current output before continuing.",
];

export const BG_START_PARAMETER_DESCRIPTIONS = {
	command:
		"Shell command line to run in the background (sh -c on POSIX, cmd.exe /d /s /c on Windows). It receives no stdin (EOF immediately); interactive commands will not work.",
	title: "Short human-readable name shown in listings and the UI",
	workingDir: "Working directory (default: current working directory)",
};

export const BG_STATUS_TOOL_DESCRIPTION =
	"Peek at a background terminal's status and current output (tail-truncated) without blocking. If the terminal already exited, this returns its final state.";

export const BG_STATUS_PARAMETER_DESCRIPTIONS = {
	id: 'Terminal id, e.g. "bt-1"',
};

export const BG_LIST_TOOL_DESCRIPTION =
	"List all background terminals (running and settled) with pid, elapsed time, exit status, and output sizes.";

export const BG_KILL_TOOL_DESCRIPTION =
	"Stop one or more running background terminals (SIGTERM to the whole process tree, escalating to SIGKILL). Returns each terminal's final state; already-settled ids are reported as such.";

export const BG_KILL_PARAMETER_DESCRIPTIONS = {
	ids: 'Terminal ids to stop, e.g. ["bt-1"]',
};

export function buildStartResult(snap: TerminalSnapshot) {
	return (
		`Started background terminal ${snap.id} "${snap.title}" (pid ${snap.pid ?? "?"}, ${snap.cwd}).\n` +
		`It runs in the background with no stdin. You'll get a message when it exits, ` +
		`or use bg_status(id: "${snap.id}") to peek, bg_kill to stop it, bg_list to see all.`
	);
}

/** One metadata line: `bt-1 [running] "dev server" (pid 12345, 3m12s, exit -, /path)`. */
export function describeTerminal(snap: TerminalSnapshot) {
	const details = [
		`pid ${snap.pid ?? "?"}`,
		formatElapsed(snap),
		snap.status === "running" ? "exit -" : formatExit(snap),
		snap.cwd,
		`stdout ${formatSize(snap.stdout.totalBytes)}, stderr ${formatSize(snap.stderr.totalBytes)}`,
	];
	return `${snap.id} [${snap.status}] "${snap.title}" (${details.join(", ")})`;
}

/** Tail-truncated labeled output section with a pointer at the full log. */
function outputSection(
	label: string,
	view: TerminalSnapshot["stdout"],
	maxBytes: number,
	maxLines: number,
) {
	if (view.totalBytes === 0) return `${label}: (empty)`;
	const truncation = truncateTail(view.text, {
		maxBytes: Math.min(maxBytes, DEFAULT_MAX_BYTES),
		maxLines: Math.min(maxLines, DEFAULT_MAX_LINES),
	});
	let text = `${label}:\n${truncation.content}`;
	const shownBytes = truncation.outputBytes;
	if (truncation.truncated || view.truncatedBytes > 0) {
		const where = view.spillPath
			? `Full log: ${view.spillPath}`
			: "Full output in the /ps viewer";
		text += `\n[${label} truncated: showing last ${formatSize(shownBytes)} of ${formatSize(view.totalBytes)}. ${where}]`;
	}
	return text;
}

export function buildStatusResult(snap: TerminalSnapshot) {
	let text = describeTerminal(snap);
	if (snap.errorText) text += `\nError: ${snap.errorText}`;
	text += `\n\n${outputSection("stdout", snap.stdout, STATUS_STDOUT_MAX, STATUS_STDOUT_MAX_LINES)}`;
	text += `\n\n${outputSection("stderr", snap.stderr, STATUS_STDERR_MAX, STATUS_STDERR_MAX_LINES)}`;
	return text;
}

/** The async completion follow-up injected into the model's context. */
export function buildTerminalResultMessage(snap: TerminalSnapshot) {
	const how =
		snap.status === "killed" ? "was killed" : `exited (${formatExit(snap)})`;
	let text = `Background terminal ${snap.id} "${snap.title}" ${how} after ${formatElapsed(snap)}.`;
	if (snap.errorText) text += `\nError: ${snap.errorText}`;
	text += `\n\n${outputSection("stdout", snap.stdout, RESULT_STDOUT_MAX, RESULT_STDOUT_MAX_LINES)}`;
	if (snap.stderr.totalBytes > 0) {
		text += `\n\n${outputSection("stderr", snap.stderr, RESULT_STDERR_MAX, RESULT_STDERR_MAX_LINES)}`;
	}
	return text;
}

export function buildKillReport(results: ReadonlyArray<KillResult>) {
	return results
		.map((entry) => {
			if (entry.killed) {
				return `Killed ${entry.id} "${entry.title}" (${entry.exit}).`;
			}
			if (entry.wasRunning) {
				// The natural exit won the race with the kill signal.
				return `${entry.id} "${entry.title}" exited on its own before the kill landed (${entry.exit}).`;
			}
			return `${entry.id} "${entry.title}" was already ${entry.status} (${entry.exit}).`;
		})
		.join("\n");
}

/**
 * OutputBuffer — bounded in-memory capture of one process stream.
 *
 * Newest output is always retained; when the retained size exceeds the cap,
 * whole chunks are evicted from the head and counted in `truncatedBytes`.
 * A single chunk larger than the cap itself is trimmed to its tail (on a
 * UTF-8 boundary) so retention is strictly bounded even for one giant write.
 * An optional spill callback receives every chunk (in order, before any
 * eviction) so the caller can keep a complete on-disk copy.
 *
 * Plain TS by design: this is push-based accumulation driven by node stream
 * 'data' callbacks, not stream transformation.
 */

import type { OutputView } from "./domain.ts";

export class OutputBuffer {
	private chunks: string[] = [];
	/** Bytes currently retained across `chunks`. */
	private retainedBytes = 0;
	/** Cached join of `chunks`; invalidated on push so 1Hz UI ticks are cheap. */
	private cachedText: string | undefined = "";
	/** Bumped on every push; lets the UI cache derived line layouts. */
	version = 0;
	totalBytes = 0;
	truncatedBytes = 0;
	spillPath?: string;

	private readonly maxRetainedBytes: number;
	private readonly spill?: (chunk: string) => unknown;

	constructor(maxRetainedBytes: number, spill?: (chunk: string) => unknown) {
		this.maxRetainedBytes = maxRetainedBytes;
		this.spill = spill;
	}

	push(chunk: string) {
		if (chunk.length === 0) return true;
		let bytes = Buffer.byteLength(chunk, "utf8");
		this.totalBytes += bytes;
		const spillAccepted = this.spill?.(chunk) !== false;
		if (bytes > this.maxRetainedBytes) {
			// A single pathological chunk larger than the whole cap: everything
			// retained so far precedes it in the stream, so evict all of it, then
			// keep only the chunk's tail (cut on a UTF-8 code point boundary).
			// Retention stays strictly bounded even for one giant write, and the
			// retained view stays contiguous (no hole in the middle).
			this.truncatedBytes += this.retainedBytes;
			this.chunks = [];
			this.retainedBytes = 0;
			const raw = Buffer.from(chunk, "utf8");
			let start = raw.length - this.maxRetainedBytes;
			while (start < raw.length && (raw[start] & 0xc0) === 0x80) start++;
			this.truncatedBytes += start;
			chunk = raw.subarray(start).toString("utf8");
			bytes = raw.length - start;
		}
		this.chunks.push(chunk);
		this.retainedBytes += bytes;
		while (
			this.retainedBytes > this.maxRetainedBytes &&
			this.chunks.length > 1
		) {
			const evicted = this.chunks.shift();
			if (evicted === undefined) break;
			const evictedBytes = Buffer.byteLength(evicted, "utf8");
			this.retainedBytes -= evictedBytes;
			this.truncatedBytes += evictedBytes;
		}
		this.cachedText = undefined;
		this.version++;
		return spillAccepted;
	}

	view(): OutputView {
		this.cachedText ??= this.chunks.join("");
		return {
			text: this.cachedText,
			totalBytes: this.totalBytes,
			truncatedBytes: this.truncatedBytes,
			spillPath: this.spillPath,
		};
	}
}

/**
 * Deferred one-shot delivery map (same semantics as subagents'): a settled
 * terminal's result is held here until it is either drained into a follow-up
 * message or consumed by a tool call (bg_kill / bg_status) that already
 * returned the settlement itself. Keyed by id, so double delivery is
 * structurally impossible — whoever drains first wins.
 */
export function createDeferredResultDelivery<T extends { id: string }>() {
	const pending = new Map<string, T>();

	return {
		defer(result: T) {
			pending.set(result.id, result);
		},
		consume(ids: Iterable<string>) {
			for (const id of ids) pending.delete(id);
		},
		drain() {
			const results = [...pending.values()];
			pending.clear();
			return results;
		},
		clear() {
			pending.clear();
		},
	};
}

/**
 * /ps UI — two-stage full-screen overlay over the synchronous
 * TerminalReadModel:
 * - TerminalDashboard: list of all tracked terminals (select, kill, open).
 * - TerminalDetailView: read-only inspector for one terminal — metadata,
 *   stdout/stderr toggle, scrolling, live tail. No input surface: background
 *   terminals have no stdin by design.
 */

import type {
	ExtensionCommandContext,
	KeybindingsManager,
	Theme,
} from "@earendil-works/pi-coding-agent";
import { formatSize } from "@earendil-works/pi-coding-agent";
import type { Component, TUI } from "@earendil-works/pi-tui";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";
import { formatElapsed, formatExit, type TerminalSnapshot } from "../domain.ts";
import type { TerminalReadModel } from "../manager.ts";
import { createOutputLineCache, sanitizeText } from "./output-view.ts";

/** One-line-safe rendering of model-provided text (titles, commands): a
 * newline or control char inside a fixed-height row desyncs the renderer. */
function oneLine(text: string) {
	return sanitizeText(text.replace(/\s+/g, " "));
}

function configuredKeys(
	keybindings: KeybindingsManager,
	binding: Parameters<KeybindingsManager["getKeys"]>[0],
) {
	return keybindings.getKeys(binding).join("/") || "unbound";
}

function statusGlyph(snap: TerminalSnapshot, theme: Theme) {
	switch (snap.status) {
		case "running":
			return theme.fg("warning", "■");
		case "done":
			return theme.fg("success", "■");
		case "failed":
			return theme.fg("error", "■");
		case "killed":
			return theme.fg("muted", "■");
	}
}

function statusWord(snap: TerminalSnapshot, theme: Theme) {
	switch (snap.status) {
		case "running":
			return theme.fg("warning", "running");
		case "done":
			return theme.fg("success", "done");
		case "failed":
			return theme.fg("error", "failed");
		case "killed":
			return theme.fg("muted", "killed");
	}
}

// --- Entry point ---------------------------------------------------------------

export async function openTerminalPicker(
	ctx: ExtensionCommandContext,
	view: TerminalReadModel,
) {
	const selection: DashboardSelection = { index: 0 };

	while (true) {
		if (view.size() === 0) {
			ctx.ui.notify("No background terminals", "info");
			return;
		}

		const picked = await ctx.ui.custom<string | null>(
			(tui, theme, keybindings, done) =>
				new TerminalDashboard(tui, theme, keybindings, view, selection, done),
			{
				overlay: true,
				overlayOptions: { anchor: "center", width: "100%", maxHeight: "100%" },
			},
		);

		if (!picked) return;
		if (!view.get(picked)) continue;

		await ctx.ui.custom<null>(
			(tui, theme, keybindings, done) =>
				new TerminalDetailView(tui, theme, keybindings, picked, view, done),
			{
				overlay: true,
				overlayOptions: { anchor: "center", width: "100%", maxHeight: "100%" },
			},
		);
		// After leaving the detail view, fall back to the dashboard.
	}
}

// --- Dashboard (fullscreen overlay) ----------------------------------------------

export interface DashboardSelection {
	id?: string;
	index: number;
}

export function reconcileDashboardSelection(
	selection: DashboardSelection,
	terminals: ReadonlyArray<Pick<TerminalSnapshot, "id">>,
) {
	const stableIndex = selection.id
		? terminals.findIndex((snap) => snap.id === selection.id)
		: -1;
	selection.index =
		stableIndex >= 0
			? stableIndex
			: Math.min(
					Math.max(0, selection.index),
					Math.max(0, terminals.length - 1),
				);
	selection.id = terminals[selection.index]?.id;
}

class TerminalDashboard implements Component {
	private tui: TUI;
	private theme: Theme;
	private keybindings: KeybindingsManager;
	private view: TerminalReadModel;
	private selection: DashboardSelection;
	private done: (value: string | null) => void;

	private closed = false;
	private ticker: ReturnType<typeof setInterval>;
	private unsubChange: () => void;

	constructor(
		tui: TUI,
		theme: Theme,
		keybindings: KeybindingsManager,
		view: TerminalReadModel,
		selection: DashboardSelection,
		done: (value: string | null) => void,
	) {
		this.tui = tui;
		this.theme = theme;
		this.keybindings = keybindings;
		this.view = view;
		this.selection = selection;
		this.done = done;
		// Elapsed times and output sizes tick along at 1Hz.
		this.ticker = setInterval(() => this.tui.requestRender(), 1000);
		this.unsubChange = view.subscribe(() => this.tui.requestRender());
	}

	private terminals(): ReadonlyArray<TerminalSnapshot> {
		return this.view.list();
	}

	private cleanup() {
		if (this.closed) return false;
		this.closed = true;
		clearInterval(this.ticker);
		this.unsubChange();
		return true;
	}

	private close(result: string | null) {
		if (this.cleanup()) this.done(result);
	}

	dispose(): void {
		this.cleanup();
	}

	handleInput(data: string): void {
		const terminals = this.terminals();
		reconcileDashboardSelection(this.selection, terminals);

		if (this.keybindings.matches(data, "tui.select.cancel")) {
			this.close(null);
			return;
		}
		if (this.keybindings.matches(data, "tui.select.confirm")) {
			const snap = terminals[this.selection.index];
			if (snap) this.close(snap.id);
			return;
		}
		if (this.keybindings.matches(data, "tui.select.up") || data === "k") {
			if (terminals.length > 0) {
				this.selection.index =
					(this.selection.index - 1 + terminals.length) % terminals.length;
				this.selection.id = terminals[this.selection.index]?.id;
				this.tui.requestRender();
			}
			return;
		}
		if (this.keybindings.matches(data, "tui.select.down") || data === "j") {
			if (terminals.length > 0) {
				this.selection.index = (this.selection.index + 1) % terminals.length;
				this.selection.id = terminals[this.selection.index]?.id;
				this.tui.requestRender();
			}
			return;
		}
		if (data === "x") {
			const snap = terminals[this.selection.index];
			if (snap && snap.status === "running") this.view.requestKill(snap.id);
			return;
		}
	}

	private pad(text: string, width: number): string {
		const truncated = truncateToWidth(text, width);
		return truncated + " ".repeat(Math.max(0, width - visibleWidth(truncated)));
	}

	private borderSegment(width: number, title: string): string {
		const theme = this.theme;
		const label = title
			? ` ${truncateToWidth(title, Math.max(0, width - 3))} `
			: "";
		const labelWidth = visibleWidth(label);
		return (
			theme.fg("border", "─") +
			(label ? theme.fg("text", label) : "") +
			theme.fg("border", "─".repeat(Math.max(0, width - 1 - labelWidth)))
		);
	}

	render(width: number): string[] {
		const theme = this.theme;
		const terminals = this.terminals();
		reconcileDashboardSelection(this.selection, terminals);

		const rows = this.tui.terminal.rows || 30;
		// Render exactly terminal rows - 1 so the overlay covers the header,
		// chat, editor, and extra footer lines while leaving pi's final footer
		// row visible.
		const bodyHeight = Math.max(6, rows - 5);
		const innerWidth = width - 2;

		const lines: string[] = [];

		// Header: title left, count right
		const headerLeft = theme.fg("accent", theme.bold("Background terminals"));
		const headerRight = theme.fg(
			"muted",
			`${terminals.length} terminal${terminals.length === 1 ? "" : "s"}`,
		);
		const headerPad = Math.max(
			1,
			width - visibleWidth(headerLeft) - visibleWidth(headerRight) - 4,
		);
		lines.push(
			truncateToWidth(
				`  ${headerLeft}${" ".repeat(headerPad)}${headerRight}  `,
				width,
			),
		);

		// Top border with panel title
		const running = terminals.filter((s) => s.status === "running").length;
		lines.push(
			theme.fg("border", "╭") +
				this.borderSegment(
					innerWidth,
					`terminals · ${running} running / ${terminals.length}`,
				) +
				theme.fg("border", "╮"),
		);

		// Rows
		const divider = theme.fg("border", "│");
		const rowLines = this.renderRows(terminals, innerWidth, bodyHeight);
		for (let i = 0; i < bodyHeight; i++) {
			lines.push(divider + this.pad(rowLines[i] ?? "", innerWidth) + divider);
		}

		// Bottom border
		lines.push(
			theme.fg("border", "╰") +
				theme.fg("border", "─".repeat(Math.max(0, innerWidth))) +
				theme.fg("border", "╯"),
		);

		// Hints
		lines.push(
			truncateToWidth(
				theme.fg(
					"dim",
					`  ${configuredKeys(this.keybindings, "tui.select.up")}/${configuredKeys(this.keybindings, "tui.select.down")}/jk select · ${configuredKeys(this.keybindings, "tui.select.confirm")} inspect · x kill · ${configuredKeys(this.keybindings, "tui.select.cancel")} close`,
				),
				width,
			),
		);

		return lines;
	}

	private renderRows(
		terminals: ReadonlyArray<TerminalSnapshot>,
		width: number,
		height: number,
	): string[] {
		const theme = this.theme;
		const out: string[] = [];

		// Scroll window around selection
		let start = 0;
		if (terminals.length > height) {
			start = Math.min(
				Math.max(0, this.selection.index - Math.floor(height / 2)),
				terminals.length - height,
			);
		}
		const visible = terminals.slice(start, start + height);

		for (let i = 0; i < visible.length; i++) {
			const snap = visible[i];
			const index = start + i;
			const isSelected = index === this.selection.index;

			// Left: marker, status square, title, dim id
			const marker = isSelected ? theme.fg("accent", "❯") : " ";
			const title = isSelected
				? theme.fg("accent", oneLine(snap.title))
				: theme.fg("text", oneLine(snap.title));
			const left = ` ${marker} ${statusGlyph(snap, theme)} ${title} ${theme.fg("dim", snap.id)}`;

			// Right: pid · elapsed · exit/status
			const dot = theme.fg("dim", " · ");
			const rightParts = [
				theme.fg("muted", `pid ${snap.pid ?? "?"}`),
				theme.fg("muted", formatElapsed(snap)),
				snap.status === "running"
					? statusWord(snap, theme)
					: theme.fg("muted", formatExit(snap)),
			];
			const right = `${rightParts.join(dot)} `;

			const rightWidth = visibleWidth(right);
			const leftMax = Math.max(0, width - rightWidth - 2);
			const leftTruncated = truncateToWidth(left, leftMax);
			const gap = Math.max(2, width - visibleWidth(leftTruncated) - rightWidth);
			out.push(truncateToWidth(leftTruncated + " ".repeat(gap) + right, width));
		}

		if (start > 0) {
			out[0] = truncateToWidth(theme.fg("dim", `   ... ${start} more`), width);
		}
		if (start + height < terminals.length) {
			out[out.length - 1] = truncateToWidth(
				theme.fg("dim", `   ... ${terminals.length - start - height} more`),
				width,
			);
		}
		return out;
	}

	invalidate(): void {}
}

// --- Detail view (read-only inspector) --------------------------------------------

const OUTPUT_SCROLL_STEP = 6;

class TerminalDetailView implements Component {
	private tui: TUI;
	private theme: Theme;
	private keybindings: KeybindingsManager;
	private id: string;
	private view: TerminalReadModel;
	private done: (value: null) => void;

	/** Active output stream shown in the viewport; `t` toggles. */
	private stream: "stdout" | "stderr" = "stdout";
	/** Scroll offset in lines from the bottom. 0 = pinned to bottom (live tail). */
	private scrollOffset = 0;
	private lineCache = createOutputLineCache();
	private unsubscribe: () => void;
	private renderTimer?: ReturnType<typeof setTimeout>;
	private ticker: ReturnType<typeof setInterval>;
	private closed = false;

	constructor(
		tui: TUI,
		theme: Theme,
		keybindings: KeybindingsManager,
		id: string,
		view: TerminalReadModel,
		done: (value: null) => void,
	) {
		this.tui = tui;
		this.theme = theme;
		this.keybindings = keybindings;
		this.id = id;
		this.view = view;
		this.done = done;
		this.unsubscribe = view.subscribeTo(id, () => this.scheduleRender());
		// Elapsed time in the header ticks along at 1Hz.
		this.ticker = setInterval(() => this.tui.requestRender(), 1000);
	}

	private snap(): TerminalSnapshot | undefined {
		return this.view.get(this.id);
	}

	private scheduleRender() {
		if (this.renderTimer) return;
		// A chatty process emits a chunk per write. Limit terminal repaints so
		// this view cannot starve input handling.
		this.renderTimer = setTimeout(() => {
			this.renderTimer = undefined;
			if (!this.closed) this.tui.requestRender();
		}, 50);
	}

	private cleanup() {
		if (this.closed) return false;
		this.closed = true;
		this.unsubscribe();
		clearInterval(this.ticker);
		if (this.renderTimer) clearTimeout(this.renderTimer);
		this.renderTimer = undefined;
		return true;
	}

	private close() {
		if (this.cleanup()) this.done(null);
	}

	dispose(): void {
		this.cleanup();
	}

	handleInput(data: string): void {
		if (
			this.keybindings.matches(data, "app.interrupt") ||
			this.keybindings.matches(data, "tui.select.cancel")
		) {
			this.close();
			return;
		}
		if (data === "t") {
			this.stream = this.stream === "stdout" ? "stderr" : "stdout";
			this.lineCache = createOutputLineCache();
			this.scrollOffset = 0;
			this.tui.requestRender();
			return;
		}
		if (data === "x") {
			const snap = this.snap();
			if (snap?.status === "running") this.view.requestKill(this.id);
			return;
		}
		if (this.keybindings.matches(data, "tui.editor.cursorUp") || data === "k") {
			this.scrollOffset += OUTPUT_SCROLL_STEP;
			this.tui.requestRender();
			return;
		}
		if (
			this.keybindings.matches(data, "tui.editor.cursorDown") ||
			data === "j"
		) {
			this.scrollOffset = Math.max(0, this.scrollOffset - OUTPUT_SCROLL_STEP);
			this.tui.requestRender();
			return;
		}
		if (this.keybindings.matches(data, "tui.editor.pageUp")) {
			this.scrollOffset += this.viewportHeight();
			this.tui.requestRender();
			return;
		}
		if (this.keybindings.matches(data, "tui.editor.pageDown")) {
			this.scrollOffset = Math.max(
				0,
				this.scrollOffset - this.viewportHeight(),
			);
			this.tui.requestRender();
			return;
		}
		if (data === "g") {
			this.scrollOffset = Number.MAX_SAFE_INTEGER; // clamped to top in render
			this.tui.requestRender();
			return;
		}
		if (data === "G") {
			this.scrollOffset = 0;
			this.tui.requestRender();
			return;
		}
	}

	private viewportHeight(): number {
		const rows = this.tui.terminal.rows || 30;
		// The complete view renders viewport + 8 chrome rows (borders, header,
		// command, tab, hints). rows - 9 makes the overlay ~terminal rows - 1.
		return Math.max(6, rows - 9);
	}

	render(width: number): string[] {
		const theme = this.theme;
		const border = theme.fg("borderAccent", "─".repeat(Math.max(1, width)));
		const lines: string[] = [];
		const snap = this.snap();

		if (!snap) {
			lines.push(border);
			lines.push(theme.fg("dim", `${this.id} is no longer tracked`));
			lines.push(border);
			return lines;
		}

		lines.push(border);
		const header =
			`${statusGlyph(snap, theme)} ` +
			theme.fg("accent", theme.bold(`${snap.id} · ${oneLine(snap.title)}`)) +
			theme.fg(
				"muted",
				` · ${snap.status} · ${formatElapsed(snap)} · pid ${snap.pid ?? "?"}`,
			) +
			(snap.status !== "running"
				? theme.fg("muted", ` · ${formatExit(snap)}`)
				: "") +
			theme.fg("dim", ` · ${snap.cwd}`);
		lines.push(truncateToWidth(header, width));
		lines.push(
			truncateToWidth(
				theme.fg("dim", "$ ") + theme.fg("text", oneLine(snap.command)),
				width,
			),
		);
		lines.push(border);

		// Stream tab line: which stream is active, both sizes.
		const active = this.stream;
		const viewData = active === "stdout" ? snap.stdout : snap.stderr;
		const tab = (name: "stdout" | "stderr", size: number) =>
			name === active
				? theme.fg("accent", theme.bold(`${name} (${formatSize(size)})`))
				: theme.fg("dim", `${name} (${formatSize(size)})`);
		lines.push(
			truncateToWidth(
				`  ${tab("stdout", snap.stdout.totalBytes)}${theme.fg("dim", " | ")}${tab("stderr", snap.stderr.totalBytes)}${theme.fg("dim", "  — t to switch")}`,
				width,
			),
		);

		// Fixed-height output viewport. Notes and scroll status consume rows
		// inside the viewport so streaming/scrolling never changes overlay height.
		const buffer = viewData;
		const version =
			// The cached view text identity changes with the buffer; totalBytes is a
			// monotonically increasing proxy for a version counter.
			buffer.totalBytes;
		const output = this.lineCache.get(buffer.text, version, width - 2);
		const viewport = this.viewportHeight();

		const noteRows: string[] = [];
		if (snap.errorText) {
			noteRows.push(
				truncateToWidth(
					theme.fg("error", `error: ${oneLine(snap.errorText)}`),
					width,
				),
			);
		}
		if (buffer.truncatedBytes > 0) {
			noteRows.push(
				truncateToWidth(
					theme.fg(
						"dim",
						`first ${formatSize(buffer.truncatedBytes)} dropped from view — full log: ${buffer.spillPath ?? "(unavailable)"}`,
					),
					width,
				),
			);
		}

		const body: string[] = [...noteRows];
		const scrollRows = this.scrollOffset > 0 ? 1 : 0;
		const capacity = Math.max(1, viewport - body.length - scrollRows);
		const maxOffset = Math.max(0, output.length - capacity);
		if (this.scrollOffset > maxOffset) this.scrollOffset = maxOffset;

		const end = output.length - this.scrollOffset;
		const visible = output.slice(Math.max(0, end - capacity), end);
		if (visible.length === 0) {
			body.push(theme.fg("dim", `(no ${active} yet)`));
		} else {
			for (const line of visible) {
				body.push(truncateToWidth(`  ${line}`, width));
			}
		}

		if (this.scrollOffset > 0) {
			body.push(
				truncateToWidth(
					theme.fg("dim", `... ${this.scrollOffset} lines below · ↓/pgdn`),
					width,
				),
			);
		}
		while (body.length < viewport) body.push("");
		lines.push(...body.slice(0, viewport));

		lines.push(border);
		lines.push(
			truncateToWidth(
				theme.fg(
					"dim",
					`${configuredKeys(this.keybindings, "tui.select.cancel")} back · t stdout/stderr · x kill · ${configuredKeys(this.keybindings, "tui.editor.cursorUp")}/${configuredKeys(this.keybindings, "tui.editor.cursorDown")}/jk scroll · ${configuredKeys(this.keybindings, "tui.editor.pageUp")}/${configuredKeys(this.keybindings, "tui.editor.pageDown")} page · g/G top/bottom`,
				),
				width,
			),
		);
		lines.push(border);
		return lines;
	}

	invalidate(): void {}
}

/**
 * Output rendering for the /ps detail view: turns a captured stream's text
 * into sanitized, wrapped display lines. Sanitization happens here — at
 * render time, never at capture time — because raw ANSI/control characters
 * desync the TUI renderer and smear the overlay.
 */

import { wrapTextWithAnsi } from "@earendil-works/pi-tui";

// OSC strings (window titles, hyperlinks, etc.) end in BEL or ST. Strip them
// before the generic escape/control pass so their payload never becomes
// visible text after only the leading ESC byte is removed.
// eslint-disable-next-line no-control-regex
const OSC_PATTERN =
	/(?:\u001b\]|\u009d)(?:[^\u0007\u001b\u009c]|\u001b(?!\\))*(?:\u0007|\u001b\\|\u009c)/g;
// Standards-shaped CSI matcher: parameters are deliberately unbounded; a
// five-digit cursor movement is still one control sequence, not visible text.
// eslint-disable-next-line no-control-regex
const CSI_PATTERN = /(?:\u001b\[|\u009b)[0-?]*[ -/]*[@-~]/g;
// Remaining two-byte/charset escape forms (for example ESC ( 0).
// eslint-disable-next-line no-control-regex
const ESCAPE_PATTERN = /\u001b(?:[()][0-2A-Z]|[ -/]*[@-~])/g;

/**
 * Strip raw ANSI codes, expand tabs, and drop control chars. Terminal-expanded
 * tabs (and stray escapes) make lines wider than the width we declare to the
 * TUI, which desyncs the renderer.
 */
export function sanitizeText(text: string) {
	return text
		.replace(OSC_PATTERN, "")
		.replace(CSI_PATTERN, "")
		.replace(ESCAPE_PATTERN, "")
		.replaceAll("\t", "  ")
		.replace(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g, "");
}

/** Split, sanitize, and wrap a stream's text into display lines. */
export function buildOutputLines(text: string, width: number) {
	const safeWidth = Math.max(10, width);
	const out: string[] = [];
	for (const raw of text.split("\n")) {
		// Carriage-return progress lines (npm, cargo): keep only the final state.
		const segments = raw.split("\r");
		const finalSegment = segments.at(-1) ?? "";
		const lastSegment =
			finalSegment || [...segments].reverse().find((segment) => segment) || "";
		const clean = sanitizeText(lastSegment);
		if (clean.length === 0) {
			out.push("");
			continue;
		}
		out.push(...wrapTextWithAnsi(clean, safeWidth));
	}
	// Drop one trailing empty line from a trailing "\n" so the tail pin sits
	// on the last real output line.
	if (out.length > 0 && out[out.length - 1] === "") out.pop();
	return out;
}

/**
 * Cache of wrapped lines keyed by (buffer version, width): a chatty process
 * bumps the version per chunk, but renders between chunks (1Hz elapsed ticks,
 * scrolling) must not re-wrap megabytes.
 */
export function createOutputLineCache() {
	let key: string | undefined;
	let lines: string[] = [];
	return {
		get(text: string, version: number, width: number) {
			const nextKey = `${version}:${width}`;
			if (key !== nextKey) {
				key = nextKey;
				lines = buildOutputLines(text, width);
			}
			return lines;
		},
	};
}

/**
 * Background terminals — start long-running shell processes the model can
 * inspect and stop, but never write to (stdin is ignored at the OS level).
 *
 * Tools (for the LLM):
 * - bg_start: fire-and-forget spawn (command, title, working_dir). Max 8
 *   running at once. The model is notified exactly once when a process exits.
 * - bg_status: peek at one terminal's status + tail-truncated output.
 * - bg_list: list all tracked terminals (running and settled).
 * - bg_kill: SIGTERM→SIGKILL the whole process tree; returns final state.
 *
 * While ≥1 process runs, a one-line widget above the editor shows
 * "N background terminal(s) running • /ps to view". `/ps` opens a two-stage
 * full-screen overlay (list → read-only detail with stdout/stderr toggle).
 *
 * Plain TypeScript: the manager is constructed lazily in session_start (not
 * in the factory — pi docs warn against spawning background resources in the
 * factory). Tool handlers call async manager methods directly (no runtime
 * indirection). Node stream plumbing inside the manager is plain callbacks.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import type {
	ExtensionAPI,
	ExtensionContext,
	ExtensionUIContext,
} from "@earendil-works/pi-coding-agent";
import { getMarkdownTheme } from "@earendil-works/pi-coding-agent";
import { Markdown, Text } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import type { TerminalSnapshot } from "./src/domain.ts";
import { TerminalManager } from "./src/manager.ts";
import {
	BG_KILL_PARAMETER_DESCRIPTIONS,
	BG_KILL_TOOL_DESCRIPTION,
	BG_LIST_TOOL_DESCRIPTION,
	BG_START_PARAMETER_DESCRIPTIONS,
	BG_START_PROMPT_GUIDELINES,
	BG_START_PROMPT_SNIPPET,
	BG_START_TOOL_DESCRIPTION,
	BG_STATUS_PARAMETER_DESCRIPTIONS,
	BG_STATUS_TOOL_DESCRIPTION,
	buildKillReport,
	buildStartResult,
	buildStatusResult,
	buildTerminalResultMessage,
	describeTerminal,
} from "./src/prompt.ts";
import { createDeferredResultDelivery } from "./src/result-delivery.ts";
import { sanitizeText } from "./src/ui/output-view.ts";
import { openTerminalPicker } from "./src/ui/ps.ts";

const WIDGET_KEY = "background-terminals";

export default function (pi: ExtensionAPI) {
	let manager: TerminalManager | undefined;
	let sessionContext: ExtensionContext | undefined;
	let ui: ExtensionUIContext | undefined;
	let unsubStatus: (() => void) | undefined;
	const resultDelivery = createDeferredResultDelivery<TerminalSnapshot>();

	/** One-line widget directly above the editor, only while ≥1 is running.
	 * Called on every manager notification (including per-output-chunk), so it
	 * only touches setWidget when the running count actually changes —
	 * replacing the widget factory hundreds of times a second would churn
	 * component creation for no visible difference. */
	let widgetRunning = 0;
	const updateWidget = (mgr: TerminalManager) => {
		if (!ui) return;
		try {
			const running = mgr.view
				.list()
				.filter((snap) => snap.status === "running").length;
			if (running === widgetRunning) return;
			widgetRunning = running;
			if (running === 0) {
				ui.setWidget(WIDGET_KEY, undefined);
				return;
			}
			ui.setWidget(WIDGET_KEY, (_tui, theme) => {
				const line =
					theme.fg("warning", "■ ") +
					theme.fg(
						"text",
						`${running} background terminal${running === 1 ? "" : "s"} running`,
					) +
					theme.fg("dim", " • ") +
					theme.fg("accent", "/ps") +
					theme.fg("dim", " to view");
				return { render: () => [line], invalidate: () => {} };
			});
		} catch {
			// UI may be unavailable (print/RPC modes or teardown).
		}
	};

	const deliverResult = (snap: TerminalSnapshot) => {
		try {
			pi.sendMessage(
				{
					customType: "background-terminal-result",
					content: buildTerminalResultMessage(snap),
					display: true,
					details: {
						id: snap.id,
						title: snap.title,
						status: snap.status,
						exitCode: snap.exitCode,
						signal: snap.signal,
					},
				},
				// followUp: queued until the agent has no more tool calls — never
				// interrupts a mid-turn stream. triggerTurn: wakes the model
				// immediately iff idle; if busy, the queued follow-up is delivered
				// when the current run settles. Either way exactly one delivery.
				{ deliverAs: "followUp", triggerTurn: true },
			);
			return true;
		} catch (error) {
			// Session may be shutting down, but retain the snapshot so any later
			// agent-settled flush can retry instead of silently dropping it.
			console.error("background-terminals: failed to deliver result", error);
			return false;
		}
	};

	const flushResults = () => {
		for (const snap of resultDelivery.drain()) {
			if (!deliverResult(snap)) resultDelivery.defer(snap);
		}
	};

	const onSettled = (snap: TerminalSnapshot, consumed: boolean) => {
		if (consumed) {
			// An in-flight bg_kill is returning this settlement itself.
			resultDelivery.consume([snap.id]);
			return;
		}
		// Defer a deep-enough copy: the live snapshot's output views keep
		// mutating (late flushes) after settle.
		resultDelivery.defer({
			...snap,
			stdout: { ...snap.stdout },
			stderr: { ...snap.stderr },
		});
		if (sessionContext?.isIdle()) flushResults();
	};

	// Construct the manager lazily in session_start (NOT in the factory — pi
	// docs warn: do not spawn/start background resources in the factory; defer
	// to session_start).
	pi.on("session_start", (_event, ctx) => {
		sessionContext = ctx;
		if (ctx.hasUI) ui = ctx.ui;
		manager ??= new TerminalManager();
		manager.view.setOnSettled(onSettled);
		unsubStatus?.();
		unsubStatus = manager.view.subscribe(() => updateWidget(manager!));
		updateWidget(manager);
	});

	// Drain deferred results when the agent settles: together with the
	// isIdle() fast path above and the Map-keyed delivery (drain clears),
	// double delivery is structurally impossible — whoever drains first wins.
	// NOTE: the reference used "agent_settled"; this pi version exposes
	// "agent_end" (fired when an agent loop ends) as the closest equivalent.
	pi.on("agent_end", flushResults);

	// /new, /resume, /fork, /reload, and quit all emit session_shutdown for
	// the old extension instance. Processes never survive a session
	// transition: disposeAll kills every entry's process tree (SIGTERM→SIGKILL),
	// each close bounded so a wedged process cannot hang shutdown.
	pi.on("session_shutdown", async () => {
		sessionContext = undefined;
		resultDelivery.clear();
		unsubStatus?.();
		unsubStatus = undefined;
		try {
			ui?.setWidget(WIDGET_KEY, undefined);
		} catch {
			// UI may already be gone.
		}
		widgetRunning = 0;
		ui = undefined;
		const m = manager;
		manager = undefined;
		await m?.disposeAll();
	});

	// --- Tools -------------------------------------------------------------

	pi.registerTool({
		name: "bg_start",
		label: "Start Background Terminal",
		description: BG_START_TOOL_DESCRIPTION,
		promptSnippet: BG_START_PROMPT_SNIPPET,
		promptGuidelines: BG_START_PROMPT_GUIDELINES,
		parameters: Type.Object({
			command: Type.String({
				description: BG_START_PARAMETER_DESCRIPTIONS.command,
			}),
			title: Type.String({
				description: BG_START_PARAMETER_DESCRIPTIONS.title,
			}),
			working_dir: Type.Optional(
				Type.String({
					description: BG_START_PARAMETER_DESCRIPTIONS.workingDir,
				}),
			),
		}),
		async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
			if (!manager) throw new Error("Session not started.");

			const command = params.command.trim();
			if (!command) throw new Error("command must not be empty.");

			const cwd = path.resolve(ctx.cwd, params.working_dir ?? ".");
			if (!fs.existsSync(cwd) || !fs.statSync(cwd).isDirectory()) {
				throw new Error(`working_dir is not a directory: ${cwd}`);
			}

			// Collapse whitespace (a newline inside a one-line UI row desyncs the
			// TUI renderer) before bounding the length.
			const title =
				params.title.replace(/\s+/g, " ").trim().slice(0, 80) || "terminal";
			const snap = await manager.start({ command, title, cwd });

			return {
				content: [{ type: "text", text: buildStartResult(snap) }],
				details: { id: snap.id, title: snap.title, cwd, pid: snap.pid },
			};
		},
	});

	pi.registerTool({
		name: "bg_status",
		label: "Check Background Terminal",
		description: BG_STATUS_TOOL_DESCRIPTION,
		parameters: Type.Object({
			id: Type.String({ description: BG_STATUS_PARAMETER_DESCRIPTIONS.id }),
		}),
		async execute(_toolCallId, params) {
			if (!manager) throw new Error("Session not started.");
			const snap = manager.view.get(params.id);
			if (!snap) {
				const known = manager.view.list().map((s) => s.id);
				throw new Error(
					`Unknown terminal id "${params.id}". Known: ${known.join(", ") || "none"}.`,
				);
			}

			// This status is returning the settlement itself; a pending automatic
			// follow-up for the same settle would be a duplicate.
			if (snap.status !== "running") resultDelivery.consume([snap.id]);

			return {
				content: [{ type: "text", text: buildStatusResult(snap) }],
				details: {
					id: snap.id,
					status: snap.status,
					pid: snap.pid,
					exitCode: snap.exitCode,
					signal: snap.signal,
				},
			};
		},
	});

	pi.registerTool({
		name: "bg_list",
		label: "List Background Terminals",
		description: BG_LIST_TOOL_DESCRIPTION,
		parameters: Type.Object({}),
		async execute() {
			if (!manager) throw new Error("Session not started.");
			const terminals = manager.view.list();
			const text =
				terminals.length === 0
					? "No background terminals."
					: terminals.map((snap) => describeTerminal(snap)).join("\n");
			return {
				content: [{ type: "text", text }],
				details: {
					terminals: terminals.map((snap) => ({
						id: snap.id,
						title: snap.title,
						status: snap.status,
						pid: snap.pid,
					})),
				},
			};
		},
	});

	pi.registerTool({
		name: "bg_kill",
		label: "Kill Background Terminals",
		description: BG_KILL_TOOL_DESCRIPTION,
		parameters: Type.Object({
			ids: Type.Array(Type.String(), {
				description: BG_KILL_PARAMETER_DESCRIPTIONS.ids,
			}),
		}),
		async execute(_toolCallId, params, _signal) {
			if (!manager) throw new Error("Session not started.");
			const ids = [...new Set(params.ids)];
			if (ids.length === 0)
				throw new Error("Provide at least one terminal id.");

			const known = manager.view.list().map((snap) => snap.id);
			const unknown = ids.filter((id) => !manager!.view.get(id));
			if (unknown.length > 0) {
				throw new Error(
					`Unknown terminal id(s): ${unknown.join(", ")}. Known: ${known.join(", ") || "none"}.`,
				);
			}

			const report = await manager.kill(ids);

			// Settlement may have happened before this kill began (or during it,
			// via the killInterest consumed flag). Remove any deferred automatic
			// delivery now that this tool returns the final state itself.
			resultDelivery.consume(ids);

			return {
				content: [{ type: "text", text: buildKillReport(report) }],
				details: {
					results: report.map((entry) => ({
						id: entry.id,
						title: entry.title,
						status: entry.status,
						killed: entry.killed,
					})),
				},
			};
		},
	});

	// --- Result message rendering ------------------------------------------

	pi.registerMessageRenderer(
		"background-terminal-result",
		(message, { expanded }, theme) => {
			const details = (message.details ?? {}) as {
				id?: string;
				title?: string;
				status?: string;
				exitCode?: number;
				signal?: string;
			};
			const failed = details.status === "failed";
			const killed = details.status === "killed";
			const icon = failed
				? theme.fg("error", "x")
				: killed
					? theme.fg("muted", "■")
					: theme.fg("success", "■");
			const how = killed
				? "killed"
				: (details.signal ?? `exit ${details.exitCode ?? "?"}`);
			const header =
				`${icon} ` +
				theme.fg("accent", theme.bold(`terminal ${details.id ?? "?"}`)) +
				theme.fg("muted", ` · ${details.title ?? ""} · ${how}`);

			const content =
				typeof message.content === "string" ? message.content : "";
			// Remove only the summary line; the Error line (when present) is part
			// of the actual result and must remain visible. The body carries raw
			// process output — sanitize ANSI/control chars or the transcript smears.
			const body = sanitizeText(
				content.split("\n").slice(1).join("\n").trim(),
			);

			if (expanded) {
				const md = new Markdown(`${body}`, 0, 0, getMarkdownTheme());
				const container = new Text(header, 0, 0);
				return {
					render: (width: number) => [
						...container.render(width),
						...md.render(width),
					],
					invalidate: () => {
						container.invalidate();
						md.invalidate();
					},
				};
			}

			const previewLines = body.split("\n").slice(0, 8);
			let text = header;
			for (const line of previewLines)
				text += `\n${theme.fg("toolOutput", line)}`;
			if (body.split("\n").length > 8)
				text += `\n${theme.fg("dim", "... (ctrl+o to expand)")}`;
			return new Text(text, 0, 0);
		},
	);

	// --- Command ------------------------------------------------------------

	pi.registerCommand("ps", {
		description: "List and inspect background terminals",
		handler: async (_args, ctx) => {
			if (!manager) throw new Error("Session not started.");
			if (ctx.mode !== "tui") {
				if (ctx.hasUI) {
					const terminals = manager.view.list();
					ctx.ui.notify(
						terminals.length === 0
							? "No background terminals."
							: terminals
									.map((snap) => describeTerminal(snap))
									.join("\n"),
						"info",
					);
				}
				return;
			}
			if (manager.view.size() === 0) {
				ctx.ui.notify(
					"No background terminals yet. The agent starts them with bg_start.",
					"info",
				);
				return;
			}
			await openTerminalPicker(ctx, manager.view);
		},
	});
}
